<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { withBase } from 'vitepress'
import captcha from '../../data/generated/captcha.json'

// One real challenge generated by the Go renderer (cmd/docgen).
const sample = captcha.samples.find((s) => s.kind === 'image')!
const geo = captcha.geometry
const cellStyle = (i: number) => {
  const r = Math.floor(i / geo.n), c = i % geo.n
  const pct = (px: number) => `${(px / geo.size) * 100}%`
  return {
    left: pct(geo.margin + c * (geo.cell + geo.gap)),
    top: pct(geo.margin + r * (geo.cell + geo.gap)),
    width: pct(geo.cell),
    height: pct(geo.cell),
  }
}

// Timeline of the scripted demo; each entry is how long a step lasts (ms).
const durations = [1600, 1400, 1600, 1400, 650, 650, 900, 1500, 1600, 2600]
const step = ref(0)
const viewer = ref<'alice' | 'others'>('alice')
const reduced = ref(false)
let timer: ReturnType<typeof setTimeout> | undefined

function schedule() {
  timer = setTimeout(() => {
    step.value = (step.value + 1) % durations.length
    schedule()
  }, durations[step.value])
}

onMounted(() => {
  reduced.value = window.matchMedia('(prefers-reduced-motion: reduce)').matches
  if (reduced.value) {
    step.value = 7
    return
  }
  schedule()
})
onBeforeUnmount(() => clearTimeout(timer))

const joined = computed(() => step.value >= 1)
const serviceGone = computed(() => step.value >= 2)
const prompt = computed(() => step.value >= 2 && step.value < 8)
const card = computed(() => viewer.value === 'alice' && step.value >= 3 && step.value < 8)
const picks = computed(() => (step.value >= 7 ? 3 : Math.max(0, step.value - 3)))
const passed = computed(() => step.value >= 7)
const welcome = computed(() => viewer.value === 'alice' && step.value >= 8)
const aliceSays = computed(() => step.value >= 9)
const pickIndex = (cell: number) => sample.answer.slice(0, picks.value).indexOf(cell)
</script>

<template>
  <div class="hero-chat" aria-label="TAdmin 浮层验证演示">
    <div class="viewer" role="tablist" aria-label="切换视角">
      <button role="tab" :aria-selected="viewer === 'alice'" :class="{ on: viewer === 'alice' }" @click="viewer = 'alice'">
        以新人 Alice 视角
      </button>
      <button role="tab" :aria-selected="viewer === 'others'" :class="{ on: viewer === 'others' }" @click="viewer = 'others'">
        以其他群友视角
      </button>
    </div>
    <div class="window">
      <header>
        <span class="avatar">开</span>
        <div>
          <strong>开源爱好者交流群</strong>
          <small>1,024 位成员 · TAdmin 守护中</small>
        </div>
      </header>
      <div class="body">
        <div class="msg">
          <span class="who" style="color: #e0752d">Bob</span>
          今晚发布 v2 了，欢迎来试 🎉
        </div>

        <Transition name="pop">
          <div v-if="joined && !serviceGone" class="service">Alice 加入了群组</div>
        </Transition>

        <Transition name="pop">
          <div v-if="prompt" class="msg bot">
            <span class="who">TAdmin</span>
            👋 欢迎 <a>Alice</a> 加入！请点击下方按钮完成人机验证（只有你能看到题目），限时 3 分钟。
            <div class="kb">
              <span class="primary">🔐 开始验证</span>
              <span>✅ 放行</span><span>🚫 移除</span>
            </div>
          </div>
        </Transition>

        <Transition name="rise">
          <div v-if="card" class="msg eph" :class="{ done: passed }">
            <span class="eph-tag">👁 仅你可见</span>
            <template v-if="!passed">
              <div class="board">
                <img :src="withBase(sample.image)" alt="3×3 图形点选验证题" width="540" height="540" />
                <span v-for="i in 9" :key="i" class="cell" :style="cellStyle(i - 1)">
                  <b v-if="pickIndex(i - 1) >= 0">{{ pickIndex(i - 1) + 1 }}</b>
                </span>
              </div>
              <p class="prompt">{{ sample.prompt_zh }}</p>
            </template>
            <p v-else class="ok">✅ 验证通过，欢迎！现在可以发言了。</p>
          </div>
        </Transition>

        <Transition name="rise">
          <div v-if="welcome" class="msg eph">
            <span class="eph-tag">👁 仅你可见</span>
            🎉 欢迎 Alice 加入 <b>开源爱好者交流群</b>！先看看置顶的群规吧。
          </div>
        </Transition>

        <Transition name="pop">
          <div v-if="aliceSays" class="msg">
            <span class="who" style="color: #8b5cf6">Alice</span>
            大家好 👋
          </div>
        </Transition>

        <Transition name="pop">
          <p v-if="viewer === 'others' && step >= 3 && step < 8" class="hint">
            其他群友只看到一行欢迎提示——题目不会刷屏。
          </p>
        </Transition>
      </div>
    </div>
  </div>
</template>

